from abc import ABCMeta, abstractproperty
from collections import namedtuple

import attr
import six
from typing import Optional, Dict, Union  # noqa: F401


@six.add_metaclass(ABCMeta)
class OpticalSwitch(object):
    def __init__(self, addr, model, port=None):
        # type: (str, str, Optional[int])  -> None
        """

        :param addr: ip_address of switch
        :param module_amount: amount of modules in switch, eg. for model Leoni `6x4` the amount is 6
        :param channel_amount: amount of channels in module, eg. for model Leoni`6x4` the amount is 4
        :param port: port to connect to, defaults to None

        After creating this class object, parameter `modules` can be accessed. It's a dict, where key
        is module number (starting from 1) and value is SwitchModule object, from which SwitchChannels
        can be accessed (in param `channels`, which is a dict with channel numbers starting from 1).
        Eg. to access the first channel of first module use: `self.modules[1].channels[1]`.
        """
        self.addr = addr
        self.port = port
        self.model = model
        self.vendor = self.__class__.__name__
        self.modules = {
            i: SwitchModule(self, i, self.channel_amount) for i in range(1, self.module_amount + 1)
        }  # type: Dict[Union[int, str], Union[SwitchModule, CalientModule]]

    @abstractproperty
    def module_amount(self):
        """Specified by model"""

    @abstractproperty
    def channel_amount(self):
        """ Specified by model"""


@attr.s(cmp=False)
class SwitchModule(object):
    optical_switch = attr.ib(type=OpticalSwitch)
    module_no = attr.ib(type=int)
    channel_amount = attr.ib(repr=False, type=int)
    channels = attr.ib(init=False)

    def __attrs_post_init__(self):
        self.channels = {i: SwitchChannel(self.optical_switch, self, i) for i in range(1, self.channel_amount + 1)}


@attr.s(cmp=False)
class SwitchChannel(object):
    optical_switch = attr.ib(type=OpticalSwitch)
    switch_module = attr.ib(type=SwitchModule)
    channel_no = attr.ib(type=int)


class Leoni(OpticalSwitch):
    leoni_params = namedtuple('leoni_params', ['module_amount', 'channel_amount'])
    model_params = {
        'mol 12x(2x12)': leoni_params(2, 12),
        'mol 10x(1x2)': leoni_params(10, 2),
        'mol 8x(3x8)': leoni_params(3, 8),
        'mol 6x(2x6)': leoni_params(6, 4),
        'mol 5x(2x6)': leoni_params(5, 4),
        'mol 2x(1x8)': leoni_params(1, 8),
        'mol 2x(3x8)': leoni_params(3, 8),
        'mol 2x(4x8)': leoni_params(4, 8),
    }

    def __init__(self, addr, model, port=None):
        # type: (str, str, Optional[int]) -> None
        super(Leoni, self).__init__(addr, model, port)

    @property
    def module_amount(self):
        return self.model_params[self.model].module_amount

    @property
    def channel_amount(self):
        return self.model_params[self.model].channel_amount


@attr.s(cmp=False)
class CalientModule(SwitchModule):
    """
    :param OpticalSwitch optical_switch: optical_switch Object
    :param int module_no: means input port no in Calient
    :param int channel_amount: output ports amount
    """
    def __attrs_post_init__(self):
        self.module_no = Calient.get_port_no_formatted(self.module_no)
        self.channels = {Calient.get_port_no_formatted(i):
                         CalientChannel(self.optical_switch, self, i)
                         for i in range(1, self.channel_amount + 1)}


@attr.s(cmp=False)
class CalientChannel(SwitchChannel):
    """
    :param OpticalSwitch optical_switch: optical_switch Object
    :param SwitchModule switch_module: switch_module object
    :param int channel_no: in Calient, means output port no
    """

    def __attrs_post_init__(self):
        self.channel_no = Calient.get_port_no_formatted(self.channel_no)


class Calient(OpticalSwitch):
    calient_params = namedtuple('calient_params', ['input_port_amount', 'output_port_amount'])
    model_params = {'S320': calient_params(324, 324)}

    def __init__(self, addr, model, username, password, port=80):
        # type: (str, str, str, str, Optional[int]) -> None
        """
        :param str addr: ip_address of switch
        :param str model: model of Calient, eg. S320
        :param str username: username of optical_switch
        :param str password: password of optical_switch
        :param int port: port to connect to, in Calient defaults to 80
        """
        super(Calient, self).__init__(addr, model, port)
        self.username = username
        self.password = password
        self.modules = {self.get_port_no_formatted(i): CalientModule(self, i, self.channel_amount)
                        for i in range(1, self.module_amount + 1)}

    @classmethod
    def get_port_no_formatted(cls, port_no):
        # type: (int) -> str
        """
        convert port_no to formatted value. eg. 1--> '1.1.1', 8-->'1.1.8', 9-->'1.2.1'
        :param int port_no: port_no value, minimum value is 1
        :return: formatted port_no.
        """
        port_oct_str = cls._convert_to_oct_str(port_no - 1)
        return cls._convert_port_str(port_oct_str)

    @staticmethod
    def _convert_to_oct_str(decimal_value):
        """
        convert decimal_value to octal value string with 3 digits, eg. 0-->000, 1->001, 8->010
        """
        return str(int(oct(decimal_value).replace('o', ''))).zfill(3)

    @staticmethod
    def _convert_port_str(port_no_str):
        """
        add '111' and dot to 'xxx', eg. '000'-->'1.1.1', '112' --> '2.2.3'
        """
        return '.'.join([str(int(item) + 1) for item in list(port_no_str)])

    @property
    def module_amount(self):
        return self.model_params[self.model].input_port_amount

    @property
    def channel_amount(self):
        return self.model_params[self.model].output_port_amount


class Mitron(OpticalSwitch):
    mitron_params = namedtuple('mitron_params', ['input_port_amount', 'output_port_amount'])
    model_params = {'OXC1000-32X32-SM-1356-DD-50-LP': mitron_params(32, 32)}

    def __init__(self, addr, model, port=None):
        # type: (str, str, Optional[int]) -> None
        super(Mitron, self).__init__(addr, model, port)

    @property
    def module_amount(self):
        return self.model_params[self.model].input_port_amount

    @property
    def channel_amount(self):
        return self.model_params[self.model].output_port_amount


@attr.s(cmp=False)
class Agiltron(OpticalSwitch):
    """
    :param str addr: ip_address of switch
    :param str community_read: snmp community for read (maintenance page -> NMC Manage -> Network -> SNMP -> WriteCom)
    :param str community_write: snmp community for write (maintenance page -> NMC Manage -> Network -> SNMP -> ReadCom)
    :param str slot: slot number (maintenance page -> Card Manage -> Card Basic Info -> slot)
    """

    community_read = attr.ib(default='public', type=str)
    community_write = attr.ib(default='private', type=str)
    slot = attr.ib(default='4', type=str)
    input_ports = attr.ib(default=32, type=int)
    max_routes = attr.ib(default=2, type=int)

    @property
    def module_amount(self):
        return self.input_ports

    @property
    def channel_amount(self):
        return self.max_routes
